//! Generated by `cargo xtask codegen` from the link registry's chart constants (`crates/ledger/src/links.rs`,
//! their values the constants register's, `crates/ledger/src/constants.rs`) and the register's curve projection
//! search constants; do not edit.

use spirv_std::num_traits::{Float, NumCast};

/// The chart constants at a float type (dd_generation_root §3.9; REQ-DEC-009): the decode and encode formulae
/// and the link functions read each by name, never as a literal.
pub trait ChartConstants: Copy {
    /// `mu_max` = 5.0.
    const MU_MAX: Self;

    /// `q_max` = 2.0.
    const Q_MAX: Self;

    /// `alpha_min` = 0.0.
    const ALPHA_MIN: Self;

    /// `eps_mu` = 1e-6.
    const EPS_MU: Self;

    /// `eps_z` = 1e-6.
    const EPS_Z: Self;

    /// `eps_q` = 1e-6.
    const EPS_Q: Self;

    /// `delta_lambda` = 1e-12.
    const DELTA_LAMBDA: Self;

    /// `eps_w` = 1e-10.
    const EPS_W: Self;

    /// `eps_m01` = 1e-5.
    const EPS_M01: Self;
}

impl ChartConstants for f32 {
    const MU_MAX: f32 = 5.0;
    const Q_MAX: f32 = 2.0;
    const ALPHA_MIN: f32 = 0.0;
    const EPS_MU: f32 = 1e-6;
    const EPS_Z: f32 = 1e-6;
    const EPS_Q: f32 = 1e-6;
    const DELTA_LAMBDA: f32 = 1e-12;
    const EPS_W: f32 = 1e-10;
    const EPS_M01: f32 = 1e-5;
}

impl ChartConstants for f64 {
    const MU_MAX: f64 = 5.0;
    const Q_MAX: f64 = 2.0;
    const ALPHA_MIN: f64 = 0.0;
    const EPS_MU: f64 = 1e-6;
    const EPS_Z: f64 = 1e-6;
    const EPS_Q: f64 = 1e-6;
    const DELTA_LAMBDA: f64 = 1e-12;
    const EPS_W: f64 = 1e-10;
    const EPS_M01: f64 = 1e-5;
}

/// The tunable link parameters' values at a float type (R-481 G7; dd_generation_root §3.9, "Tunable
/// parameters"): one field per tunable parameter of the registry, which the link functions' `_at` forms read in
/// place of the chart constant of its name, so a parameter change is a value and not a compiled variant. On the
/// GPU it is a uniform (TASK-M4-21).
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct LinkParams<R> {
    /// `mu_max`, tunable on `softmax_tanh`.
    pub mu_max: R,
    /// `q_max`, tunable on `sigmoid_q`, `tanh_q`, `softsign_q`.
    pub q_max: R,
}

impl<R: ChartConstants> LinkParams<R> {
    /// The defaults, each field its chart constant (R-481 A2): the link functions at them are bitwise those that
    /// read the constants.
    pub const DEFAULT: Self = LinkParams {
        mu_max: R::MU_MAX,
        q_max: R::Q_MAX,
    };
}

/// `tanh_sat` = 20.0: a chart constant an operator reads, not a tree (dd_generation_root §3.9), at the float
/// type `R`, the register entry's value converted from f32, where it is exact. Emitted as a function of `R`
/// rather than a [`ChartConstants`] item: an operator's bound is one number at every float type the links are
/// evaluated at, not a per-type choice, so a type outside the kernel's two (a test's dual number) reads it too.
/// Were the conversion ever to fail, the bound would be `R`'s largest finite value, and the operator unclamped.
#[inline]
pub fn tanh_sat<R: Float>() -> R {
    let v: f32 = 20.0;
    <R as NumCast>::from(v).unwrap_or_else(R::max_value)
}

/// The register's `curve_grid_log2`: the curve projection's search grid has `2^CURVE_GRID_LOG2` cells
/// (dd_encode §3.4), so its spacing is the span times a power of two, exact.
pub const CURVE_GRID_LOG2: i32 = 6;

/// The search grid's cells, `2^CURVE_GRID_LOG2`: `CURVE_GRID + 1` points, the span's edges included.
pub const CURVE_GRID: u32 = 64;

/// The register's `curve_golden_steps`: the golden-section steps inside the best grid point's two cells, a
/// fixed count (dd_encode §3.4).
pub const CURVE_GOLDEN_STEPS: u32 = 80;

/// The register's `inv_phi`: `1/φ = (√5 − 1)/2`, the golden section's ratio, the f64 nearest; its rounding to
/// f32 is the f32 nearest as well (dd_encode §3.4).
pub const INV_PHI: f64 = 0.6180339887498949;
